-- Theory questions: MTH 101, PHY 102, STA 112 (self-marking). Safe to run twice.
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select 'MTH 101', 'Elementary Mathematics I', 'Functions', 'Define a function. Distinguish between a one-to-one function and an onto function, giving one example of each.', 5, 'A function f from a set A to a set B is a rule that assigns to every element x of A exactly one element f(x) of B. A is the domain and B the codomain. A function is one-to-one (injective) if different inputs always give different outputs, that is f(a) = f(b) implies a = b. Example: f(x) = 2x + 1 on the real numbers. A function is onto (surjective) if every element of the codomain is the image of at least one element of the domain. Example: f(x) = x^3 from the real numbers to the real numbers, since every real number has a real cube root.', '[{"t":"Definition: every element of the domain has exactly one image","m":1},{"t":"One-to-one: different inputs give different outputs (f(a) = f(b) implies a = b)","m":1},{"t":"A correct example of a one-to-one function","m":1},{"t":"Onto: every element of the codomain is an image of some element","m":1},{"t":"A correct example of an onto function","m":1}]'::jsonb
where not exists (select 1 from public.theory_questions t where t.question = 'Define a function. Distinguish between a one-to-one function and an onto function, giving one example of each.');
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select 'MTH 101', 'Elementary Mathematics I', 'Sets', 'State De Morgan''s law for the complement of a union of two sets and prove it.', 5, 'De Morgan''s law states that the complement of (A union B) equals (A complement) intersection (B complement). Proof. Let x be in the complement of (A union B). Then x is not in A union B, so x is not in A and x is not in B. Hence x is in A complement and in B complement, so x is in their intersection. This shows the left side is contained in the right side. Conversely, let x be in (A complement) intersection (B complement). Then x is not in A and not in B, so x is not in A union B, so x is in the complement of (A union B). The two sets contain each other, so they are equal.', '[{"t":"Correct statement of the law","m":1},{"t":"Takes an element of the left side and shows it is in the right side","m":2},{"t":"Takes an element of the right side and shows it is in the left side","m":2}]'::jsonb
where not exists (select 1 from public.theory_questions t where t.question = 'State De Morgan''s law for the complement of a union of two sets and prove it.');
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select 'MTH 101', 'Elementary Mathematics I', 'Quadratic equations', 'Solve x^2 - 5x + 6 = 0 by factorisation. Define the discriminant of a quadratic equation and use it to describe the nature of the roots here.', 5, 'Factorise: x^2 - 5x + 6 = (x - 2)(x - 3) = 0, so x = 2 or x = 3. For ax^2 + bx + c = 0 the discriminant is D = b^2 - 4ac. If D is greater than 0 the roots are real and distinct, if D = 0 the roots are real and equal, and if D is less than 0 the roots are not real. Here D = (-5)^2 - 4(1)(6) = 25 - 24 = 1, which is positive, so the roots are real and distinct. This agrees with the roots 2 and 3.', '[{"t":"Correct factorisation (x - 2)(x - 3)","m":1},{"t":"Roots x = 2 and x = 3","m":1},{"t":"Discriminant defined as b^2 - 4ac","m":1},{"t":"Computes D = 1 for this equation","m":1},{"t":"States that D greater than 0 means real distinct roots","m":1}]'::jsonb
where not exists (select 1 from public.theory_questions t where t.question = 'Solve x^2 - 5x + 6 = 0 by factorisation. Define the discriminant of a quadratic equation and use it to describe the nature of the roots here.');
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select 'MTH 101', 'Elementary Mathematics I', 'Limits', 'Explain what is meant by the limit of a function as x approaches a number. Evaluate the limit of (x^2 - 4)/(x - 2) as x approaches 2.', 5, 'The limit of f(x) as x approaches a is the value that f(x) gets closer and closer to as x gets closer to a, without having to equal a. For (x^2 - 4)/(x - 2) the function is not defined at x = 2 because the denominator is zero. For x not equal to 2, factorise the numerator: x^2 - 4 = (x - 2)(x + 2). Cancel (x - 2) to get x + 2. As x approaches 2, x + 2 approaches 4. So the limit is 4, even though the function itself is undefined at x = 2.', '[{"t":"Idea of a limit: f(x) approaches a value as x approaches a, without needing f(a)","m":1},{"t":"Notes that direct substitution gives 0/0 or an undefined result","m":1},{"t":"Factorises x^2 - 4 as (x - 2)(x + 2)","m":1},{"t":"Cancels the common factor because x is not equal to 2","m":1},{"t":"Correct answer 4","m":1}]'::jsonb
where not exists (select 1 from public.theory_questions t where t.question = 'Explain what is meant by the limit of a function as x approaches a number. Evaluate the limit of (x^2 - 4)/(x - 2) as x approaches 2.');
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select 'MTH 101', 'Elementary Mathematics I', 'Binomial theorem', 'State the binomial theorem for a positive integer power n and use it to expand (1 + x)^4.', 5, 'For a positive integer n, (a + b)^n = the sum from r = 0 to n of C(n, r) a^(n - r) b^r, where C(n, r) = n!/(r!(n - r)!). For (1 + x)^4 the coefficients are C(4,0) = 1, C(4,1) = 4, C(4,2) = 6, C(4,3) = 4 and C(4,4) = 1. So (1 + x)^4 = 1 + 4x + 6x^2 + 4x^3 + x^4.', '[{"t":"Statement of the theorem with binomial coefficients C(n, r)","m":2},{"t":"Formula for C(n, r) = n!/(r!(n - r)!)","m":1},{"t":"Coefficients 1, 4, 6, 4, 1","m":1},{"t":"Final expansion 1 + 4x + 6x^2 + 4x^3 + x^4","m":1}]'::jsonb
where not exists (select 1 from public.theory_questions t where t.question = 'State the binomial theorem for a positive integer power n and use it to expand (1 + x)^4.');
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select 'MTH 101', 'Elementary Mathematics I', 'Continuity', 'State the three conditions for a function f to be continuous at x = a. Give one example of a function that fails these conditions at some point.', 5, 'f is continuous at x = a if (1) f(a) is defined, (2) the limit of f(x) as x approaches a exists, and (3) the limit equals f(a). Example of failure: f(x) = 1/x is not defined at x = 0, so it is not continuous there. Another example is a step function that jumps at a point, where the left and right limits are different so the limit does not exist.', '[{"t":"Condition 1: f(a) is defined","m":1},{"t":"Condition 2: the limit of f(x) as x approaches a exists","m":1},{"t":"Condition 3: the limit equals f(a)","m":1},{"t":"A correct example of a function that fails at a point","m":1},{"t":"Explains which condition fails in the example","m":1}]'::jsonb
where not exists (select 1 from public.theory_questions t where t.question = 'State the three conditions for a function f to be continuous at x = a. Give one example of a function that fails these conditions at some point.');
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select 'MTH 101', 'Elementary Mathematics I', 'Mathematical induction', 'Use mathematical induction to prove that 1 + 2 + 3 + ... + n = n(n + 1)/2 for every positive integer n.', 10, 'Let P(n) be the statement 1 + 2 + ... + n = n(n + 1)/2. Base case: for n = 1 the left side is 1 and the right side is 1(2)/2 = 1, so P(1) is true. Inductive step: assume P(k) is true, that is 1 + 2 + ... + k = k(k + 1)/2. Add (k + 1) to both sides. The left side becomes 1 + 2 + ... + k + (k + 1). The right side becomes k(k + 1)/2 + (k + 1) = (k + 1)(k/2 + 1) = (k + 1)(k + 2)/2. This is the formula with n = k + 1, so P(k + 1) is true. By induction, P(n) holds for every positive integer n.', '[{"t":"States the claim P(n) clearly","m":1},{"t":"Base case n = 1 checked","m":2},{"t":"States the inductive assumption P(k)","m":2},{"t":"Adds (k + 1) and simplifies to (k + 1)(k + 2)/2","m":3},{"t":"Concludes by the principle of mathematical induction","m":2}]'::jsonb
where not exists (select 1 from public.theory_questions t where t.question = 'Use mathematical induction to prove that 1 + 2 + 3 + ... + n = n(n + 1)/2 for every positive integer n.');
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select 'MTH 101', 'Elementary Mathematics I', 'Functions', 'Find the domain and the range of f(x) = square root of (x - 3).', 5, 'The square root is defined for real numbers only when the quantity inside is not negative, so x - 3 must be greater than or equal to 0, which gives x greater than or equal to 3. The domain is [3, infinity). A square root is never negative and it equals 0 when x = 3 and grows without bound as x increases. So the range is [0, infinity).', '[{"t":"Condition x - 3 greater than or equal to 0","m":1},{"t":"Domain [3, infinity)","m":1},{"t":"Notes the square root is never negative","m":1},{"t":"Range [0, infinity)","m":1},{"t":"Gives a check such as f(3) = 0","m":1}]'::jsonb
where not exists (select 1 from public.theory_questions t where t.question = 'Find the domain and the range of f(x) = square root of (x - 3).');
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select 'PHY 102', 'Electricity, Magnetism and Atomic Physics', 'Electrostatics', 'State Coulomb''s law and write it in mathematical form. State the SI unit of charge.', 5, 'Coulomb''s law states that the force between two point charges is directly proportional to the product of the charges and inversely proportional to the square of the distance between them. In symbols F = k q1 q2 / r^2, where k = 1/(4 pi epsilon-zero), about 9 x 10^9 N m^2 per C^2. The force acts along the line joining the charges and is attractive for unlike charges and repulsive for like charges. The SI unit of charge is the coulomb (C).', '[{"t":"Force is proportional to the product of the charges","m":1},{"t":"Force is inversely proportional to the square of the distance","m":1},{"t":"Formula F = k q1 q2 / r^2","m":1},{"t":"Direction: attractive for unlike charges, repulsive for like charges","m":1},{"t":"SI unit of charge is the coulomb","m":1}]'::jsonb
where not exists (select 1 from public.theory_questions t where t.question = 'State Coulomb''s law and write it in mathematical form. State the SI unit of charge.');
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select 'PHY 102', 'Electricity, Magnetism and Atomic Physics', 'Capacitors', 'Define capacitance. Derive the effective capacitance of two capacitors C1 and C2 connected in series.', 10, 'Capacitance is the charge stored per unit potential difference, C = Q/V, measured in farads. In series the same charge Q is on each capacitor. The potential differences are V1 = Q/C1 and V2 = Q/C2. The total potential difference is V = V1 + V2 = Q(1/C1 + 1/C2). The equivalent capacitance is C = Q/V, so 1/C = 1/C1 + 1/C2, which gives C = C1 C2 / (C1 + C2). The effective capacitance is smaller than either capacitor.', '[{"t":"Definition C = Q/V, unit farad","m":2},{"t":"States that the charge is the same on each capacitor in series","m":2},{"t":"Writes V1 = Q/C1 and V2 = Q/C2","m":2},{"t":"Total V = V1 + V2","m":2},{"t":"Result 1/C = 1/C1 + 1/C2 (or C1 C2/(C1 + C2))","m":2}]'::jsonb
where not exists (select 1 from public.theory_questions t where t.question = 'Define capacitance. Derive the effective capacitance of two capacitors C1 and C2 connected in series.');
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select 'PHY 102', 'Electricity, Magnetism and Atomic Physics', 'Current electricity', 'State Ohm''s law. Give two situations in which a conductor does not obey Ohm''s law.', 5, 'Ohm''s law states that the current through a conductor is directly proportional to the potential difference across it, provided the temperature and other physical conditions stay constant. In symbols V = IR where R is the resistance. It is not obeyed when the temperature changes, for example a filament lamp, whose resistance rises as it gets hot, so the graph of V against I is curved. It is also not obeyed by semiconductor devices such as diodes, whose current is not proportional to the voltage and which conduct in one direction only.', '[{"t":"Current is proportional to potential difference","m":1},{"t":"Condition: constant temperature","m":1},{"t":"Formula V = IR","m":1},{"t":"First non-ohmic example, such as a filament lamp","m":1},{"t":"Second non-ohmic example, such as a diode or other semiconductor","m":1}]'::jsonb
where not exists (select 1 from public.theory_questions t where t.question = 'State Ohm''s law. Give two situations in which a conductor does not obey Ohm''s law.');
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select 'PHY 102', 'Electricity, Magnetism and Atomic Physics', 'Circuits', 'State Kirchhoff''s current law and Kirchhoff''s voltage law, and say which conservation law each one depends on.', 5, 'Kirchhoff''s current law says that the sum of the currents entering a junction equals the sum of the currents leaving it, so the algebraic sum of currents at a junction is zero. It depends on conservation of electric charge. Kirchhoff''s voltage law says that around any closed loop the algebraic sum of the e.m.f.s equals the algebraic sum of the potential drops (IR terms). It depends on conservation of energy.', '[{"t":"Current law: total current into a junction equals total current out","m":1},{"t":"Current law linked to conservation of charge","m":1},{"t":"Voltage law: sum of e.m.f.s equals sum of IR drops around a closed loop","m":1},{"t":"Voltage law linked to conservation of energy","m":1},{"t":"Mentions sign convention or the idea of algebraic sum","m":1}]'::jsonb
where not exists (select 1 from public.theory_questions t where t.question = 'State Kirchhoff''s current law and Kirchhoff''s voltage law, and say which conservation law each one depends on.');
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select 'PHY 102', 'Electricity, Magnetism and Atomic Physics', 'Electromagnetic induction', 'State Faraday''s law and Lenz''s law of electromagnetic induction.', 5, 'Faraday''s law states that the induced e.m.f. in a circuit is directly proportional to the rate of change of magnetic flux linked with the circuit, e = -N d(phi)/dt. Lenz''s law states that the direction of the induced current is such that it opposes the change in flux that produces it. The minus sign in Faraday''s law shows this. Lenz''s law is an example of conservation of energy.', '[{"t":"Faraday: induced e.m.f. proportional to rate of change of flux linkage","m":2},{"t":"Mathematical form e = -N d(phi)/dt","m":1},{"t":"Lenz: induced current opposes the change that causes it","m":1},{"t":"Link to conservation of energy or meaning of the minus sign","m":1}]'::jsonb
where not exists (select 1 from public.theory_questions t where t.question = 'State Faraday''s law and Lenz''s law of electromagnetic induction.');
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select 'PHY 102', 'Electricity, Magnetism and Atomic Physics', 'Atomic structure', 'Describe Rutherford''s alpha particle scattering experiment and state the conclusions that came from it.', 10, 'A narrow beam of alpha particles was fired at a very thin gold foil in an evacuated chamber, and the scattered particles were detected on a zinc sulphide screen that flashed when hit. Most alpha particles passed straight through, a few were deflected through large angles, and a very small number were turned back almost the way they came. Conclusions: most of the atom is empty space, since most particles went straight through. The positive charge and most of the mass is concentrated in a very small centre called the nucleus, which explains the large deflections. The nucleus is much smaller than the atom, and electrons move round it outside. This replaced the plum pudding model.', '[{"t":"Setup: alpha beam, thin gold foil, detecting screen","m":2},{"t":"Most particles pass straight through","m":2},{"t":"A few deflected through large angles and some reflected back","m":2},{"t":"Conclusion: atom is mostly empty space","m":2},{"t":"Conclusion: small, dense, positively charged nucleus","m":2}]'::jsonb
where not exists (select 1 from public.theory_questions t where t.question = 'Describe Rutherford''s alpha particle scattering experiment and state the conclusions that came from it.');
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select 'PHY 102', 'Electricity, Magnetism and Atomic Physics', 'Atomic structure', 'State the postulates of Bohr''s model of the hydrogen atom.', 5, 'Bohr''s postulates: (1) The electron moves in certain circular orbits around the nucleus without radiating energy, called stationary states. (2) Only orbits in which the angular momentum of the electron is a whole number multiple of h/2 pi are allowed, so m v r = n h/(2 pi), where n = 1, 2, 3 and so on. (3) The atom emits or absorbs radiation only when an electron jumps from one allowed orbit to another, and the photon energy equals the difference in energy of the two orbits, h f = E_initial - E_final.', '[{"t":"Electrons move in stable circular orbits without radiating","m":1},{"t":"Angular momentum is quantised, m v r = n h/(2 pi)","m":2},{"t":"Radiation is emitted or absorbed only in a jump between orbits","m":1},{"t":"Photon energy h f equals the energy difference between the two levels","m":1}]'::jsonb
where not exists (select 1 from public.theory_questions t where t.question = 'State the postulates of Bohr''s model of the hydrogen atom.');
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select 'PHY 102', 'Electricity, Magnetism and Atomic Physics', 'Electric field', 'Define electric field intensity. A charge of 2 microcoulombs is placed in a uniform field of 500 N/C. Calculate the force on it.', 5, 'Electric field intensity at a point is the force per unit positive charge placed at that point, E = F/q. It is a vector quantity measured in newtons per coulomb (N/C) or volts per metre. From E = F/q, F = qE. With q = 2 x 10^-6 C and E = 500 N/C the force is F = 2 x 10^-6 x 500 = 1 x 10^-3 N, which is 1 millinewton. The force is in the direction of the field because the charge is positive.', '[{"t":"Definition: force per unit positive charge, E = F/q","m":1},{"t":"States it is a vector with unit N/C","m":1},{"t":"Uses F = qE","m":1},{"t":"Converts 2 microcoulombs to 2 x 10^-6 C","m":1},{"t":"Answer 1 x 10^-3 N","m":1}]'::jsonb
where not exists (select 1 from public.theory_questions t where t.question = 'Define electric field intensity. A charge of 2 microcoulombs is placed in a uniform field of 500 N/C. Calculate the force on it.');
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select 'STA 112', 'Probability and Distribution Theory', 'Basic probability', 'Define a sample space and an event. State the three axioms of probability.', 5, 'A sample space S is the set of all possible outcomes of an experiment. An event is any subset of the sample space. The axioms of probability are: (1) For any event A, P(A) is greater than or equal to 0. (2) P(S) = 1. (3) If A and B are mutually exclusive events then P(A or B) = P(A) + P(B), and this extends to any countable collection of mutually exclusive events.', '[{"t":"Sample space defined as the set of all possible outcomes","m":1},{"t":"Event defined as a subset of the sample space","m":1},{"t":"Axiom 1: P(A) is not negative","m":1},{"t":"Axiom 2: P(S) = 1","m":1},{"t":"Axiom 3: additivity for mutually exclusive events","m":1}]'::jsonb
where not exists (select 1 from public.theory_questions t where t.question = 'Define a sample space and an event. State the three axioms of probability.');
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select 'STA 112', 'Probability and Distribution Theory', 'Basic probability', 'State the addition rule for two events. If P(A) = 0.4, P(B) = 0.5 and P(A and B) = 0.2, find P(A or B).', 5, 'The addition rule is P(A or B) = P(A) + P(B) - P(A and B). The overlap is subtracted because it is counted twice. Here P(A or B) = 0.4 + 0.5 - 0.2 = 0.7. For mutually exclusive events P(A and B) = 0 and the rule reduces to P(A or B) = P(A) + P(B).', '[{"t":"General formula P(A or B) = P(A) + P(B) - P(A and B)","m":2},{"t":"Explains why the overlap is subtracted","m":1},{"t":"Substitutes correctly","m":1},{"t":"Answer 0.7","m":1}]'::jsonb
where not exists (select 1 from public.theory_questions t where t.question = 'State the addition rule for two events. If P(A) = 0.4, P(B) = 0.5 and P(A and B) = 0.2, find P(A or B).');
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select 'STA 112', 'Probability and Distribution Theory', 'Conditional probability', 'Define conditional probability and independence of two events. A bag has 3 red and 2 blue balls. Two balls are drawn one after the other without replacement. Find the probability that both are red.', 5, 'The conditional probability of A given B is P(A|B) = P(A and B)/P(B) for P(B) greater than 0. Events A and B are independent if P(A and B) = P(A) P(B), which means P(A|B) = P(A). For the draws, P(first red) = 3/5. Given the first is red, 2 red remain among 4 balls, so P(second red | first red) = 2/4. The probability both are red is 3/5 x 2/4 = 6/20 = 3/10 = 0.3.', '[{"t":"Conditional probability formula P(A|B) = P(A and B)/P(B)","m":1},{"t":"Independence: P(A and B) = P(A) P(B)","m":1},{"t":"P(first red) = 3/5","m":1},{"t":"P(second red given first red) = 2/4","m":1},{"t":"Answer 3/10","m":1}]'::jsonb
where not exists (select 1 from public.theory_questions t where t.question = 'Define conditional probability and independence of two events. A bag has 3 red and 2 blue balls. Two balls are drawn one after the other without replacement. Find the probability that both are red.');
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select 'STA 112', 'Probability and Distribution Theory', 'Bayes theorem', 'State Bayes'' theorem. Machine A makes 60 percent of the items in a factory and machine B makes 40 percent. 2 percent of A''s items are defective and 5 percent of B''s items are defective. An item is picked at random and found to be defective. What is the probability that it came from machine B?', 10, 'Bayes'' theorem: P(B_i|D) = P(D|B_i) P(B_i) divided by the sum over j of P(D|B_j) P(B_j). Here P(A) = 0.6, P(B) = 0.4, P(D|A) = 0.02 and P(D|B) = 0.05. By total probability P(D) = 0.6 x 0.02 + 0.4 x 0.05 = 0.012 + 0.020 = 0.032. Then P(B|D) = (0.4 x 0.05)/0.032 = 0.020/0.032 = 0.625. So there is a 62.5 percent chance the defective item came from machine B.', '[{"t":"Correct statement of Bayes'' theorem","m":2},{"t":"Identifies the priors and the defect rates","m":2},{"t":"Total probability P(D) = 0.032","m":3},{"t":"Applies Bayes to get 0.020/0.032","m":2},{"t":"Answer 0.625","m":1}]'::jsonb
where not exists (select 1 from public.theory_questions t where t.question = 'State Bayes'' theorem. Machine A makes 60 percent of the items in a factory and machine B makes 40 percent. 2 percent of A''s items are defective and 5 percent of B''s items are defective. An item is picked at random and found to be defective. What is the probability that it came from machine B?');
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select 'STA 112', 'Probability and Distribution Theory', 'Random variables', 'Define a random variable. Distinguish between a discrete and a continuous random variable, giving one example of each.', 5, 'A random variable is a function that assigns a real number to each outcome in a sample space. A discrete random variable takes a finite or countable set of values, usually from counting. Example: the number of heads in three tosses of a coin. A continuous random variable can take any value in an interval, usually from measuring. Example: the height of a student or the time taken to finish an exam. Probabilities of discrete variables come from a probability mass function and those of continuous variables from areas under a density curve.', '[{"t":"Definition: a rule giving a number to each outcome","m":1},{"t":"Discrete: countable values","m":1},{"t":"Correct discrete example","m":1},{"t":"Continuous: any value in an interval","m":1},{"t":"Correct continuous example","m":1}]'::jsonb
where not exists (select 1 from public.theory_questions t where t.question = 'Define a random variable. Distinguish between a discrete and a continuous random variable, giving one example of each.');
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select 'STA 112', 'Probability and Distribution Theory', 'Binomial distribution', 'State the conditions for a binomial distribution and give its probability mass function, mean and variance. A fair coin is tossed 5 times. Find the probability of exactly 2 heads.', 10, 'Conditions: a fixed number n of trials, each trial has two outcomes (success or failure), the probability of success p is the same in each trial, and the trials are independent. The probability mass function is P(X = x) = C(n, x) p^x q^(n - x) for x = 0, 1, ..., n, where q = 1 - p. The mean is np and the variance is npq. For the coin, n = 5, p = 1/2 and x = 2. P(X = 2) = C(5, 2) (1/2)^2 (1/2)^3 = 10 x 1/32 = 10/32 = 5/16 = 0.3125.', '[{"t":"Conditions: fixed n, two outcomes, constant p, independent trials","m":2},{"t":"Formula P(X = x) = C(n, x) p^x q^(n - x)","m":2},{"t":"Mean np and variance npq","m":2},{"t":"Substitutes n = 5, p = 1/2, x = 2 and C(5, 2) = 10","m":2},{"t":"Answer 5/16 or 0.3125","m":2}]'::jsonb
where not exists (select 1 from public.theory_questions t where t.question = 'State the conditions for a binomial distribution and give its probability mass function, mean and variance. A fair coin is tossed 5 times. Find the probability of exactly 2 heads.');
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select 'STA 112', 'Probability and Distribution Theory', 'Expectation and variance', 'Define the expectation and variance of a discrete random variable. X takes the values 1, 2 and 3 with probabilities 0.2, 0.5 and 0.3. Find E(X) and Var(X).', 10, 'The expectation of a discrete random variable is E(X) = sum of x P(X = x). The variance is Var(X) = E[(X - mu)^2] = E(X^2) - [E(X)]^2. Here E(X) = 1(0.2) + 2(0.5) + 3(0.3) = 0.2 + 1.0 + 0.9 = 2.1. E(X^2) = 1(0.2) + 4(0.5) + 9(0.3) = 0.2 + 2.0 + 2.7 = 4.9. Var(X) = 4.9 - (2.1)^2 = 4.9 - 4.41 = 0.49.', '[{"t":"E(X) = sum of x P(X = x)","m":1},{"t":"Var(X) = E(X^2) - [E(X)]^2","m":2},{"t":"E(X) = 2.1","m":2},{"t":"E(X^2) = 4.9","m":3},{"t":"Var(X) = 0.49","m":2}]'::jsonb
where not exists (select 1 from public.theory_questions t where t.question = 'Define the expectation and variance of a discrete random variable. X takes the values 1, 2 and 3 with probabilities 0.2, 0.5 and 0.3. Find E(X) and Var(X).');
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select 'STA 112', 'Probability and Distribution Theory', 'Normal distribution', 'State four properties of the normal distribution. If X is normally distributed with mean 50 and variance 16, find the probability that X is greater than 58. (Use P(Z less than 2) = 0.9772.)', 5, 'Properties: the curve is bell shaped and symmetric about the mean. Mean, median and mode are equal. The total area under the curve is 1. The curve approaches the horizontal axis but never touches it, and about 68 percent of values lie within one standard deviation of the mean, 95 percent within two. Standardise: the standard deviation is the square root of 16 = 4, so Z = (58 - 50)/4 = 2. P(X greater than 58) = P(Z greater than 2) = 1 - 0.9772 = 0.0228.', '[{"t":"Any two correct properties (bell shaped and symmetric, mean = median = mode)","m":1},{"t":"Any two further correct properties (total area 1, empirical 68-95 rule)","m":1},{"t":"Standard deviation 4 found from variance 16","m":1},{"t":"Z = (58 - 50)/4 = 2","m":1},{"t":"Answer 0.0228","m":1}]'::jsonb
where not exists (select 1 from public.theory_questions t where t.question = 'State four properties of the normal distribution. If X is normally distributed with mean 50 and variance 16, find the probability that X is greater than 58. (Use P(Z less than 2) = 0.9772.)');
select course_code, count(*) as questions from public.theory_questions group by course_code order by course_code;
